const settingSecretsPresent = `-- name: SettingSecretsPresent :many
SELECT section, (secrets_ciphertext IS NOT NULL)::boolean AS configured
FROM installation_settings
ORDER BY section
`

type SettingSecretsPresentRow struct {
	Section    string `json:"section"`
	Configured bool   `json:"configured"`
}

// Whether a secret exists, without returning it. It is what the panel shows in
// place of the value: "configured" is the only safe rendering of a secret.
func (q *Queries) SettingSecretsPresent(ctx context.Context) ([]SettingSecretsPresentRow, error) {
	rows, err := q.db.Query(ctx, settingSecretsPresent)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SettingSecretsPresentRow{}
	for rows.Next() {
		var i SettingSecretsPresentRow
		if err := rows.Scan(&i.Section, &i.Configured); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

